/// 名字的首字母。英文取大写，数字和其他符号归 `#`。
String pinyinInitialOf(String name) {
  final text = name.trim();
  if (text.isEmpty) return '#';
  final code = text.codeUnitAt(0);
  if (code >= 0x61 && code <= 0x7A) return String.fromCharCode(code - 32);
  if (code >= 0x41 && code <= 0x5A) return String.fromCharCode(code);
  final index = code - _base;
  if (index >= 0 && index < _initials.length) {
    final letter = _initials[index];
    if (letter != '?') return letter;
  }
  return '#';
}

/// 按首字母排：先比字母（`#` 垫底），同字母再比名字。
///
/// 只比首字母，不逐字转拼音——名字首字相同的那几个人，谁先谁后
/// 用户看不出来，稳定就行。
int compareByPinyin(String a, String b) {
  final left = pinyinInitialOf(a);
  final right = pinyinInitialOf(b);
  if (left != right) {
    if (left == '#') return 1;
    if (right == '#') return -1;
    return left.compareTo(right);
  }
  return a.compareTo(b);
}

/// 排好序的副本，原列表不动。
List<T> sortedByPinyin<T>(List<T> items, String Function(T item) nameOf) {
  final copy = List<T>.from(items);
  copy.sort((a, b) => compareByPinyin(nameOf(a), nameOf(b)));
  return copy;
}
